package com.gerenciadorrural.modules.organizations.api;
import com.gerenciadorrural.modules.organizations.application.ResolveTenantContext; import com.gerenciadorrural.shared.tenancy.*; import jakarta.servlet.http.HttpServletRequest; import org.springframework.http.*; import org.springframework.web.bind.annotation.*; import java.util.UUID;
@RestController @RequestMapping("/api/v1/context") public class TenantContextController { public static final String ATTRIBUTE=TenantContextRequestAttribute.NAME; private final ResolveTenantContext resolver; private final TenantContextProvider contexts; public TenantContextController(ResolveTenantContext resolver,TenantContextProvider contexts){this.resolver=resolver;this.contexts=contexts;}
 @GetMapping public ResponseEntity<Response> get(@RequestHeader(value="X-Organization-Id",required=false) String organization,@RequestHeader(value="X-Farm-Id",required=false) String farm,HttpServletRequest request){if(organization==null||farm==null)throw new TenantContextHeaderException("TENANT_CONTEXT_HEADER_MISSING"); try {var result=resolver.execute(UUID.fromString(organization),UUID.fromString(farm)); request.setAttribute(ATTRIBUTE,result.context()); return ResponseEntity.ok().cacheControl(CacheControl.noStore()).body(Response.from(new ResolveTenantContext.Resolved(contexts.requireCurrent(),result.organizationName(),result.farmName())));}catch(IllegalArgumentException e){throw new TenantContextHeaderException("TENANT_CONTEXT_HEADER_INVALID");}}
 public record Response(String userId,Organization organization,Farm farm,Membership membership){static Response from(ResolveTenantContext.Resolved r){var c=r.context();return new Response(c.userId().toString(),new Organization(c.tenantId().toString(),r.organizationName()),new Farm(c.farmId().toString(),r.farmName()),new Membership(c.membershipId().toString(),c.role(),c.farmScopeMode()));}} public record Organization(String id,String name){} public record Farm(String id,String name){} public record Membership(String id,String role,String farmScopeMode){}
}
